import { api } from './api.js';

export async function postCheckIn(checkIn) {
  return api.post('/check-ins', checkIn);
}

// Sends every queued check-in once the device is back online.
export async function flushQueue(queue, api) {
  const ordered = [...queue].sort((a, b) => b.createdAt - a.createdAt);
  for (const item of ordered) {
    await api.post('/check-ins', item);
    queue.remove(item.id);
  }
  return ordered.length;
}
import { api } from './api.js';
import { reportError } from './errors.js';

export async function postCheckIn(checkIn) {
  try {
    return await api.post('/check-ins', checkIn);
  } catch (err) {
    reportError(err, {
      tags: { area: 'sync', status: err.status ?? 'network' },
      extra: { payload: checkIn, userId: checkIn.userId, attempt: checkIn.attempt },
    });
    throw err;
  }
}

// Sends every queued check-in once the device is back online.
export async function flushQueue(queue, api) {
  const ordered = [...queue].sort((a, b) => b.createdAt - a.createdAt);
  for (const item of ordered) {
    await api.post('/check-ins', item);
    queue.remove(item.id);
  }
  return ordered.length;
}

