export function Settings({ user }) {
  return (
    <Screen title="Settings">
      <NotificationsToggle user={user} />
      {!user.premium && (
        <Card className="upgrade">
          <h3>Keep every streak safe with Premium</h3>
          <PlanPicker
            plans={[
              { id: 'monthly', label: '$1.99 / month' },
              { id: 'annual', label: '$14.99 / year (save 37%)' },
            ]}
            defaultSelected="annual"
          />
          <Button onClick={startCheckout}>Continue</Button>
          <TextButton onClick={dismissUpgrade}>
